      // c0s1 — Do you have a starter?
      'onboarding.c0s1.heading':       'Do you already have a sourdough starter?',
      'onboarding.c0s1.body':          'A sourdough starter is a mixture of flour and water that captures wild yeast from the air. If you already have one, great! If not, we\'ll walk you through creating yours from scratch — it only takes 10 minutes of hands-on time.',
      'onboarding.c0s1.btnHasStarter': 'Yes, I have a starter →',
      'onboarding.c0s1.btnMakeStarter':'Help me make one from scratch 🌾',

      // c0s2 — Starter recipe
      'onboarding.c0s2.eyebrow':      'Creating Your Starter',
      'onboarding.c0s2.heading':      'Alison\'s starter recipe',
      'onboarding.c0s2.subtitle':     'This process takes 7–10 days. You\'ll spend about 5 minutes per day. The app will remind you each day.',
      'onboarding.c0s2.day1.title':   'Day 1 — Mix & Rest',
      'onboarding.c0s2.day1.sub':     '~5 minutes hands-on',
      'onboarding.c0s2.day1.flour':   '50g all-purpose flour',
      'onboarding.c0s2.day1.wheat':   '50g whole wheat flour',
      'onboarding.c0s2.day1.water':   '100g water (room temperature)',
      'onboarding.c0s2.day1.inst':    'Mix everything in a clean jar until no dry flour remains. Cover loosely with a cloth or loosely-placed lid. Leave at room temperature (68–78°F). <strong>That\'s it for today.</strong>',
      'onboarding.c0s2.day2.title':   'Day 2 — Leave it alone',
      'onboarding.c0s2.day2.sub':     'No action required',
      'onboarding.c0s2.day2.body':    'Don\'t feed it. Don\'t stir it. The wild yeast is just beginning to wake up. You might not see much activity yet — that\'s completely normal.',
      'onboarding.c0s2.day3.title':   'Days 3–10 — Daily feeding',
      'onboarding.c0s2.day3.sub':     'Repeat every day until ready',
      'onboarding.c0s2.day3.discard': 'Discard half (pour out ~100g)',
      'onboarding.c0s2.day3.flour':   'Add 100g all-purpose flour',
      'onboarding.c0s2.day3.water':   'Add 100g water',
      'onboarding.c0s2.day3.inst':    'Stir well, cover loosely, leave at room temperature. <strong>Your starter is ready</strong> when it reliably doubles within 4–6 hours of feeding, smells pleasantly sour (like yogurt), and is full of bubbles throughout. This usually happens between Day 7–10 depending on your kitchen temperature.',
      'onboarding.c0s2.tip':          '<strong>Tip:</strong> Warmer kitchens (75°F+) move faster. Cooler kitchens (65°F) take longer. Both produce great starters — patience is the only ingredient you can\'t measure.',
      'onboarding.c0s2.btnReady':     'I\'m ready — start Day 1 →',
      'onboarding.c0s2.footerNote':   'The app will remind you daily to check in on your starter',

      // c1s1 — Meet your starter
      'onboarding.c1s1.eyebrow': 'Chapter 1 · Meet Your Starter',
      'onboarding.c1s1.heading': 'Something magical<br/>is about to begin.',
      'onboarding.c1s1.body1':   'You\'ve been given a living thing to care for — wild yeast and bacteria, woven together over time. Together, you\'ll turn flour and water into something extraordinary.',
      'onboarding.c1s1.body2':   'This is your sourdough journey. Let\'s begin.',
      'onboarding.c1s1.btn':     'Begin my journey →',

      // c1s2 — Name your starter
      'onboarding.c1s2.eyebrow':     'Name Your Starter',
