      // c2s1 — Sourdough lessons
      'onboarding.c2s1.eyebrow':    'Chapter 1 · What is Sourdough',
      'onboarding.c2s1.heading':    'What you need to know',
      'onboarding.c2s1.progress':   'Swipe or tap to continue',
