      // Lessons
      'onboarding.lesson1.h': 'What is sourdough?',
      'onboarding.lesson1.b': 'Unlike commercial yeast bread, sourdough is leavened by wild yeast and beneficial bacteria naturally present in flour and your environment. This living culture — your starter — is what makes sourdough unique. The process is slower, but the flavor, texture, and nutrition are in a completely different league.',
      'onboarding.lesson2.h': 'Your starter is alive',
      'onboarding.lesson2.b': 'A healthy starter should roughly double in size within 4–8 hours of feeding and smell pleasantly tangy — like yogurt or beer. If you see a greyish liquid on top (called "hooch"), that\'s just your starter saying it\'s hungry. Pour it off, feed it, and it\'ll bounce right back.',
      'onboarding.lesson3.h': 'The 5 stages of a bake',
      'onboarding.lesson3.b': 'Every sourdough bake follows the same rhythm: Mix → Bulk Fermentation → Shaping → Cold Proof → Bake. Your app guides you through each stage with timers and instructions. The first time feels complex. By your third bake, it feels like a familiar ritual.',
      'onboarding.lesson4.h': 'Reading your dough',
      'onboarding.lesson4.b': 'The windowpane test tells you when gluten is developed: stretch a small piece of dough thin — if it forms a translucent sheet without tearing, you\'re ready to shape. For fermentation, look for 50–75% volume increase, bubbles on the sides of your container, and a dough that jiggles when you shake it.',
      'onboarding.lesson5.h': 'Your first loaf will be ugly — and that\'s perfect',
      'onboarding.lesson5.b': 'Every incredible baker started with flat, dense, or pale loaves. That\'s not failure — that\'s data. Did it spring in the oven? How\'s the crumb? What was your bulk time? Write it in your bake notes. Sourdough baking is a practice, not a performance. Be patient with yourself.',

