      // c2game — Bulk Fermentation
      'onboarding.c2game.eyebrow':       'Interactive · Bulk Fermentation',
      'onboarding.c2game.heading':        'Watch It Rise 🔍',
      'onboarding.c2game.pill.rest':      '💤 Rest',
      'onboarding.c2game.pill.temp':      '🌡️ Temp',
      'onboarding.c2game.pill.grow':      '📈 Grow',
      'onboarding.c2game.pill.shake':     '🤝 Shake',
      'onboarding.c2game.pill.poke':      '👆 Poke',
      'onboarding.c2game.pill.pane':      '🔍 Pane',
      'onboarding.c2game.btn.startResting':'Start Resting',
      'onboarding.c2game.bakerInsight':   'Baker\'s Insight',
      'onboarding.c2game.btnNext':        'Explore: Bulk Timing →',
      'onboarding.bulk.initInst':  'Your dough is mixed and ready! Tap below to start the bulk fermentation rest.',
      'onboarding.bulk.restStart': 'Resting… dough is warming up. Tap below to check the temperature 🌡️',
      'onboarding.bulk.checkTemp': '74–78°F is the sweet spot! Now tap the bowl to watch your dough grow 📈',
      'onboarding.bulk.grow':      'Dough is growing! Now shake the bowl — tap below to do the jiggle test 🤝',
      'onboarding.bulk.shake':     'It jiggles like a marshmallow! Bubbles visible on sides. Tap the bowl for the poke test 👆',
      'onboarding.bulk.poke':      'Slowly springs back — perfect! One last test: the windowpane. Tap below 🔍',
      'onboarding.bulk.done':      '✓ Stretches thin without tearing — bulk fermentation complete! Time to shape. 🎉',
      'onboarding.bulk.btn.checkTemp':  'Check Temperature',
      'onboarding.bulk.btn.shake':      'Shake Test',
      'onboarding.bulk.btn.windowpane': 'Windowpane Test',
      'onboarding.bulk.insight0': 'The windowpane test confirms gluten development: stretch a small piece thin — if it forms a translucent sheet without tearing, bulk is complete and your dough is ready to shape.',
      'onboarding.bulk.insight1': 'Bulk fermentation is done at 50–75% volume increase — not 100% doubled. Look for bubbles on the sides, a dough that jiggles when shaken, and slow spring-back on the poke test.',
      'onboarding.bulk.insight2': 'Temperature drives everything: at 78°F bulk takes ~4–5 hours; at 68°F it can take 8–12 hours. Tracking dough temperature (not room temp!) gives you the most accurate timing.',
      'onboarding.mix.insight0': 'Adding salt last protects your starter\'s yeast activity. Salt slows fermentation — so always mix flour, water, and starter first, then fold in salt after the 1-hour rest.',
      'onboarding.mix.insight1': 'A shaggy, sticky dough after mixing is perfect! Gluten develops further during the 1-hour rest and bulk fermentation. Sourdough never needs kneading.',
      'onboarding.mix.insight2': 'The 1-hour rest after mixing (before salt) lets flour proteins fully hydrate and bond. This autolyse window builds gluten naturally — making your dough stronger with zero extra effort.',
      'onboarding.fold.insight0': 'Coil folds build the gluten network by aligning protein strands. 2–4 sets of 4 folds during the first 2 hours of bulk gives you incredible structure without over-working the dough.',
      'onboarding.fold.insight1': 'Unlike kneading, coil folds use the weight of the dough — lift it from underneath and let gravity fold it over. This builds strength while keeping gas bubbles intact.',
      'onboarding.fold.insight2': 'Your dough should feel noticeably more elastic after each set. By the last set it should hold its shape when lifted — that is the gluten network you have built!',

