      'starterKitPage.heroSubtitle': 'Toda obra maestra necesita las herramientas correctas. Hemos creado la colección definitiva para el alquimista de masa madre moderno.',
      'starterKitPage.lameDesc': 'El bisturí del artista. Domina los patrones intrincados del greñado en la masa madre.',
      'starterKitPage.lameCta': 'Aprende a Greñar',
      'starterKitPage.benchScraperDesc': 'Una extensión de tus manos para dividir y dar forma a masas de alta hidratación.',
