      // Top bar
      'onboarding.topBar.gettingStarted': 'Comenzar',
      'onboarding.topBar.quizTime':       '¡Prueba! 🎮',
      'onboarding.topBar.interactiveLab': 'Lab Interactivo 🧪',
      'onboarding.topBar.chapter':        'Capítulo',

      // c0s1
      'onboarding.c0s1.heading':       '¿Ya tienes una masa madre?',
      'onboarding.c0s1.body':          'Una masa madre es una mezcla de harina y agua que captura levadura silvestre del aire. Si ya tienes una, ¡perfecto! Si no, te guiaremos para crear la tuya desde cero — solo toma 10 minutos de trabajo activo.',
      'onboarding.c0s1.btnHasStarter': 'Sí, ya tengo masa madre →',
      'onboarding.c0s1.btnMakeStarter':'Ayúdame a hacer una 🌾',

      // c0s2
      'onboarding.c0s2.eyebrow':      'Creando Tu Masa Madre',
      'onboarding.c0s2.heading':      'La receta de masa madre de Alison',
      'onboarding.c0s2.subtitle':     'Este proceso toma 7–10 días. Dedicarás unos 5 minutos al día. La app te recordará cada día.',
      'onboarding.c0s2.day1.title':   'Día 1 — Mezclar y Reposar',
      'onboarding.c0s2.day1.sub':     '~5 minutos de trabajo activo',
      'onboarding.c0s2.day1.flour':   '50g harina de trigo todo uso',
      'onboarding.c0s2.day1.wheat':   '50g harina de trigo integral',
      'onboarding.c0s2.day1.water':   '100g agua (temperatura ambiente)',
      'onboarding.c0s2.day1.inst':    'Mezcla todo en un frasco limpio hasta que no quede harina seca. Cubre ligeramente con un paño o tapa suelta. Deja a temperatura ambiente (20–26°C). <strong>Eso es todo por hoy.</strong>',
      'onboarding.c0s2.day2.title':   'Día 2 — Déjala en paz',
      'onboarding.c0s2.day2.sub':     'Sin acción requerida',
      'onboarding.c0s2.day2.body':    'No la alimentes. No la revuelvas. La levadura silvestre apenas está despertando. Quizás no veas mucha actividad aún — eso es completamente normal.',
      'onboarding.c0s2.day3.title':   'Días 3–10 — Alimentación diaria',
      'onboarding.c0s2.day3.sub':     'Repite cada día hasta que esté lista',
      'onboarding.c0s2.day3.discard': 'Desecha la mitad (saca ~100g)',
      'onboarding.c0s2.day3.flour':   'Agrega 100g de harina todo uso',
      'onboarding.c0s2.day3.water':   'Agrega 100g de agua',
      'onboarding.c0s2.day3.inst':    'Revuelve bien, cubre ligeramente, deja a temperatura ambiente. <strong>Tu masa madre está lista</strong> cuando duplica confiablemente en 4–6 horas tras la alimentación, huele agradablemente ácida (como yogur) y está llena de burbujas. Esto suele ocurrir entre el Día 7–10 según la temperatura de tu cocina.',
      'onboarding.c0s2.tip':          '<strong>Tip:</strong> Las cocinas más cálidas (24°C+) son más rápidas. Las más frías (18°C) tardan más. Ambas producen excelentes masas madres — la paciencia es el único ingrediente que no se puede medir.',
      'onboarding.c0s2.btnReady':     'Estoy lista — empezar el Día 1 →',
      'onboarding.c0s2.footerNote':   'La app te recordará diariamente para revisar tu masa madre',

      // c1s1
      'onboarding.c1s1.eyebrow': 'Capítulo 1 · Conoce Tu Masa Madre',
      'onboarding.c1s1.heading': 'Algo mágico<br/>está a punto de comenzar.',
      'onboarding.c1s1.body1':   'Te han confiado algo vivo — levadura silvestre y bacterias, entrelazadas con el tiempo. Juntas, convertirán harina y agua en algo extraordinario.',
      'onboarding.c1s1.body2':   'Este es tu camino en el pan de masa madre. Empecemos.',
      'onboarding.c1s1.btn':     'Comenzar mi camino →',

      // c1s2
      'onboarding.c1s2.eyebrow':     'Nombra Tu Masa Madre',
      'onboarding.c1s2.heading':     '¿Cómo llamarás<br/>a tu masa madre?',
      'onboarding.c1s2.body':        'Alimentarás esta cultura viva todos los días. Dale un nombre que se sienta bien — los panaderos nombran sus masas madres igual que los marineros nombran sus barcos.',
      'onboarding.c1s2.placeholder': 'ej. Burbujita, Chispa, Miguelito…',
      'onboarding.c1s2.tip':         '¿Sin inspiración? "Burbujita" siempre es un clásico.',
      'onboarding.c1s2.btn':         'Conocer mi masa madre →',
      'onboarding.c1s2.meetName':    'Conocer a {name} →',

      // c1s3
      'onboarding.c1s3.health':  'Salud',
      'onboarding.c1s3.isAlive': ' ¡está viva!',
      'onboarding.c1s3.body':    'Una masa madre saludable duplica su tamaño después de alimentarla y huele agradablemente ácida — casi como yogur. Aprendamos a mantener la tuya floreciendo.',
      'onboarding.c1s3.btn':     'Aprendamos lo básico →',

      // c1game
      'onboarding.c1game.eyebrow': 'Capítulo 1 · ¡Hora de Prueba!',
      'onboarding.c1game.heading': 'Prueba de Masa Madre 🫧',

      // c2s1
      'onboarding.c2s1.eyebrow':    'Capítulo 1 · ¿Qué es el Sourdough?',
      'onboarding.c2s1.heading':    'Lo que necesitas saber',
      'onboarding.c2s1.progress':   'Desliza o toca para continuar',
      'onboarding.c2s1.btnGotIt':   'Entendido →',
      'onboarding.c2s1.btnContinue':'Continuar →',

      // Lessons
      'onboarding.lesson1.h': '¿Qué es el sourdough?',
      'onboarding.lesson1.b': 'A diferencia del pan con levadura comercial, el sourdough se leuda con levadura silvestre y bacterias benéficas presentes naturalmente en la harina y tu entorno. Esta cultura viva — tu masa madre — es lo que hace único al sourdough. El proceso es más lento, pero el sabor, la textura y la nutrición están en una liga completamente diferente.',
      'onboarding.lesson2.h': 'Tu masa madre está viva',
      'onboarding.lesson2.b': 'Una masa madre saludable debe aproximadamente duplicar su tamaño en 4–8 horas tras la alimentación y oler agradablemente ácida — como yogur o cerveza. Si ves un líquido grisáceo arriba (llamado "hooch"), solo significa que tu masa madre tiene hambre. Viértelo, aliméntala, y se recuperará rápidamente.',
      'onboarding.lesson3.h': 'Las 5 etapas de una horneada',
      'onboarding.lesson3.b': 'Toda horneada de sourdough sigue el mismo ritmo: Mezcla → Fermentación en Bloque → Formado → Frío Prolongado → Horneado. Tu app te guía en cada etapa con temporizadores e instrucciones. La primera vez parece complejo. Para tu tercer pan, se sentirá como un ritual familiar.',
      'onboarding.lesson4.h': 'Leyendo tu masa',
      'onboarding.lesson4.b': 'La prueba del cristal te dice cuándo el gluten está desarrollado: estira un pedazo pequeño de masa — si forma una lámina translúcida sin romperse, estás lista para formar. Para la fermentación, busca un aumento de volumen del 50–75%, burbujas en los lados del recipiente, y una masa que se tambalee cuando la agitas.',
      'onboarding.lesson5.h': 'Tu primer pan será feo — y eso es perfecto',
      'onboarding.lesson5.b': 'Toda panadero increíble comenzó con panes planos, densos o pálidos. Eso no es fracaso — son datos. ¿Subió en el horno? ¿Cómo está la miga? ¿Cuánto fue tu tiempo de fermentación? Escríbelo en tus notas de horneada. El sourdough es una práctica, no una actuación. Ten paciencia contigo misma.',

      // FB card
      'onboarding.fb.eyebrow':   'No estás sola',
      'onboarding.fb.heading':   'Únete a la comunidad Pancito y Más',
