      'onboarding.bulk.initInst':  'Tu masa está mezclada y lista. ¡Toca abajo para comenzar el reposo de fermentación en bloque!',
      'onboarding.bulk.restStart': 'Reposando… la masa se está calentando. Toca abajo para revisar la temperatura 🌡️',
      'onboarding.bulk.checkTemp': '¡74–78°F es el punto ideal! Ahora toca el tazón para ver crecer tu masa 📈',
      'onboarding.bulk.grow':      '¡La masa está creciendo! Ahora agita el tazón — toca abajo para la prueba de tambaleo 🤝',
      'onboarding.bulk.shake':     '¡Se tambalea como malvavisco! Burbujas visibles en los lados. Toca el tazón para la prueba de hundimiento 👆',
      'onboarding.bulk.poke':      '¡Regresa lentamente — perfecto! Una última prueba: el cristal. Toca abajo 🔍',
      'onboarding.bulk.done':      '✓ Se estira sin romperse — ¡fermentación en bloque completa! Hora de formar. 🎉',
      'onboarding.bulk.btn.checkTemp':  'Revisar Temperatura',
      'onboarding.bulk.btn.shake':      'Prueba de Agitación',
      'onboarding.bulk.btn.windowpane': 'Prueba del Cristal',
      'onboarding.bulk.insight0': 'La prueba del cristal confirma el desarrollo del gluten: estira un trozo pequeño — si forma una hoja translúcida sin romperse, la fermentación está completa y tu masa está lista para formar.',
      'onboarding.bulk.insight1': 'La fermentación en bloque termina con un aumento de volumen del 50–75%, no al doble. Busca burbujas en los lados, masa que se tambalea al agitarla y rebote lento en la prueba de hundimiento.',
      'onboarding.bulk.insight2': 'La temperatura lo controla todo: a 26°C la fermentación tarda ~4–5 horas; a 20°C puede tomar 8–12 horas. ¡Rastrear la temperatura de la masa (no del ambiente) te da el tiempo más preciso!',
      'onboarding.mix.insight0': 'Agregar la sal al final protege la actividad de la levadura de tu masa madre. La sal frena la fermentación, así que mezcla primero la harina, el agua y la masa madre, y añade la sal después del reposo de 1 hora.',
      'onboarding.mix.insight1': '¡Una masa pegajosa y desigual después del mezclado es perfecta! El gluten sigue desarrollándose durante el reposo de 1 hora y la fermentación en bloque. El pan de masa madre nunca necesita amasado.',
      'onboarding.mix.insight2': 'El reposo de 1 hora después del mezclado (antes de la sal) permite que las proteínas de la harina se hidraten y unan completamente. Esta ventana de autolisis construye gluten de forma natural.',
      'onboarding.fold.insight0': 'Los pliegues en espiral construyen la red de gluten alineando las hebras de proteína. 2–4 series de 4 pliegues en las primeras 2 horas de fermentación te dan una estructura increíble.',
      'onboarding.fold.insight1': 'A diferencia del amasado, los pliegues en espiral usan el peso de la masa: levántala desde abajo y deja que la gravedad la pliegue. Esto construye fuerza conservando las burbujas de gas.',
      'onboarding.fold.insight2': '¡Tu masa debe sentirse notablemente más elástica después de cada serie. En la última serie debe mantener su forma al levantarla — ¡esa es la red de gluten que has construido!',

